test("input that is not a workbook throws, it never returns an empty Book", async () => {
  const utf8 = new TextEncoder();
  const xlsx = readFileSync(XLSXWRITER);
  const pkgRels = '<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
    + '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument"'
    + ' Target="xl/workbook.xml"/></Relationships>';
  const cases = [
    ["empty buffer", new Uint8Array(0), "NOT_A_ZIP"],
    ["23 arbitrary bytes", new Uint8Array(23), "NOT_A_ZIP"],
    ["plain text", utf8.encode("this is definitely not a zip archive at all"), "NOT_A_ZIP"],
    ["csv text", utf8.encode("a,b,c\n1,2,3\n"), "NOT_A_ZIP"],
    ["json text", utf8.encode('{"sheets":[]}'), "NOT_A_ZIP"],
    ["truncated xlsx", xlsx.subarray(0, 500), "NOT_A_ZIP"],
    ["xlsx missing its end record", xlsx.subarray(0, xlsx.length - 30), "NOT_A_ZIP"],
    ["valid zip with only hello.txt", buildZip([["hello.txt", "hi"]]), "NOT_A_WORKBOOK"],
    ["opc package pointing at a missing workbook part",
      buildZip([["_rels/.rels", pkgRels], ["xl/worksheets/sheet1.xml", "<worksheet/>"]]), "NOT_A_WORKBOOK"],
    ["workbook part that is not xml",
      buildZip([["_rels/.rels", pkgRels], ["xl/workbook.xml", "this is not xml at all"]]), "NOT_A_WORKBOOK"],
    ["workbook part whose root is not workbook",
      buildZip([["_rels/.rels", pkgRels], ["xl/workbook.xml", "<foo><sheets/></foo>"]]), "NOT_A_WORKBOOK"],
  ];
  for (const [name, bytes, code] of cases) {
    assert.throws(() => readWorkbookSync(bytes), (err) => {
      assert.ok(err instanceof FormatError, name + " threw " + err.constructor.name);
      assert.ok(err instanceof GridxcelError, name);
      assert.equal(err.code, code, name + " code");
      assert.ok(err.message.length > 10, name + " message");
      return true;
    }, name);
    await assert.rejects(() => readWorkbook(bytes), (err) => err.code === code, name + " (async)");
    await assert.rejects(async () => {
      for await (const row of eachRow(bytes)) void row;
    }, (err) => err.code === code, name + " (eachRow)");
  }
  // strict must not reclassify a container error as a warning error.
  assert.throws(() => readWorkbookSync(new Uint8Array(23), { strict: true }), (err) => err.code === "NOT_A_ZIP");
  // The one case where an empty sheets array is truthful: a real workbook that
  // declares no sheets.
  const { book, warnings } = read(FIX + "reader-nosheets.xlsx");
  assert.deepEqual(book.sheets, []);
  assert.deepEqual(warnings.map((w) => w.code), ["NO_SHEETS"]);
});

