test("input forms: bytes, ArrayBuffer, path, stream, async iterable", async () => {
  const reference = readWorkbookSync(XLSXWRITER);
  const bytes = readFileSync(XLSXWRITER);
  const fromBytes = await readWorkbook(new Uint8Array(bytes));
  const fromBuffer = await readWorkbook(bytes);
  const fromArrayBuffer = await readWorkbook(bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength));
  const fromPath = await readWorkbook(XLSXWRITER);
  const stream = new ReadableStream({
    start(controller) {
      for (let i = 0; i < bytes.length; i += 8192) controller.enqueue(new Uint8Array(bytes.subarray(i, i + 8192)));
      controller.close();
    },
  });
  const fromStream = await readWorkbook(stream);
  async function* chunks() {
    for (let i = 0; i < bytes.length; i += 4096) yield new Uint8Array(bytes.subarray(i, i + 4096));
  }
  const fromIterable = await readWorkbook(chunks());
  const cellValue = (c) => (c === undefined ? undefined : c.v instanceof Date ? c.v.toISOString() : c.v);
  const key = (book) => JSON.stringify(book.sheets.map((s) => s.rows.map((r) => (r === undefined ? null : r.map(cellValue)))));
  for (const book of [fromBytes, fromBuffer, fromArrayBuffer, fromPath, fromStream, fromIterable]) {
    assert.equal(key(book), key(reference));
  }
  const url = new URL("file:///" + process.cwd().replace(/\\/g, "/") + "/" + XLSXWRITER);
  const fromUrl = await readWorkbook(url);
  assert.equal(key(fromUrl), key(reference));
  assert.equal(key(readWorkbookSync(url)), key(reference));
  await assert.rejects(() => readWorkbook(42), /unsupported workbook input/);
  assert.throws(() => readWorkbookSync(stream), /readWorkbookSync needs bytes/);
});

