const HANDMADE_SHEET1 = "xl/worksheets/sheet1.xml";

function sheetBytes() {
  return new ZipArchive(readFileSync(HANDMADE)).read(HANDMADE_SHEET1);
}

test("sheet-reader: parseSheetXml handles bytes, text and every chunk boundary", async () => {
  const bytes = sheetBytes();
  const text = new TextDecoder().decode(bytes);
  const whole = parseSheetXmlSync(text, { name: "Types2" });
  const shape = (sheet) => JSON.stringify(sheet.rows.map((r) => r && r.map((c) => c && [c.v, c.t, c.f, c.l, c.s, c.z])));
  for (const size of [1, 2, 3, 5, 7, 13, 64, 1024]) {
    const parts = [];
    for (let i = 0; i < bytes.length; i += size) parts.push(bytes.subarray(i, Math.min(i + size, bytes.length)));
    async function* chunks() { for (const p of parts) yield p; }
    const parsed = await parseSheetXml(chunks(), { name: "Types2" });
    assert.equal(shape(parsed), shape(whole), "chunk size " + size);
    assert.deepEqual(parsed.merges, whole.merges);
    assert.deepEqual(parsed.freeze, whole.freeze);
    assert.deepEqual(parsed.columns, whole.columns);
  }
  const fromBytes = parseSheetXmlSync(bytes, { name: "Types2" });
  assert.equal(shape(fromBytes), shape(whole));
});

test("sheet-reader: createRowStream is lazy and exposes sheet metadata", async () => {
  const bytes = sheetBytes();
  const stream = createRowStream(bytes);
  const rows = [];
  for await (const row of stream) {
    rows.push(row);
    if (rows.length === 2) assert.ok(stream.meta instanceof Promise);
  }
  // Row 9 holds only two value-less cells, so it produces no streamed row.
  assert.equal(rows.length, 10);
  assert.deepEqual(rows.map((r) => r.r), [1, 2, 3, 4, 5, 6, 7, 8, 10, 11]);
  assert.equal(rows[0].c0, 0);
  assert.equal(rows[0].c1, 3);
  const meta = await stream.meta;
  assert.deepEqual(meta.merges, ["A12:C13", "D4:D5"]);
  assert.equal(meta.minRow, 1);
  assert.equal(meta.maxRowNum, 11);
  assert.equal(meta.rowCount, 10);
  assert.equal(meta.maxRowNum, 11);
  // A row is handed over as soon as it closes: nothing but the current row is held.
  const many = await collect(createRowStream(bytes, { sheetStubs: true }));
  assert.equal(many.length, 11);
});

async function collect(iterable) {
  const out = [];
  for await (const item of iterable) out.push(item);
  return out;
}

